Lemma pcom_dzu_spec : forall (q p ap nx lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  sp = Z_to_bv 64 (q + -2240) -> s0 = Z_to_bv 64 q -> s2 = Z_to_bv 64 10 -> s3 = Z_to_bv 64 p -> s4 = Z_to_bv 64 105762 ->
  s5 = Z_to_bv 64 ap -> s7 = Z_to_bv 64 9 -> s8 = Z_to_bv 64 (q + -2184) -> s10 = Z_to_bv 64 (-1) -> s11 = Z_to_bv 64 37 ->
  0 < nx < 256 ->
  bytes_at asegs m p (zb8 [37; 122; 117; nx]) -> rw_cells asegs m (q + -2216) DIR0 ->
  stk asegs m lo (q + -2240) -> lo <= q + -2320 -> p + 4 <= lo -> q <= 2^47 -> 0 <= ap < 2^63 ->
  mem_inv asegs m ->
  evt asegs (pcd_post q (p + 3) (ap + 8) gp tp s0 s2 s4 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
